import { StatusView } from '../../../shared/models/status-tone.model';

/** A stock location (main store, branch, showroom…) as returned by the API. */
export interface Warehouse {
  id: string;
  /** Human-facing code, generated by the server (e.g. `WH-003`). */
  code: string;
  name: string;
  type: WarehouseType;
  city: string;
  address: string;
  manager: string;
  phone: string;
  /** Storage capacity in units — drives the usage meter. */
  capacity: number;
  /** Issuing more than the balance is allowed (stock may go below zero). */
  allowNegative: boolean;
  /** Pre-selected in documents and the POS. Exactly one warehouse is the default. */
  isDefault: boolean;
  isActive: boolean;
  notes: string;
  createdAt: string;

  // ── Computed by the server ──
  itemsCount: number;
  totalQty: number;
  stockValue: number;
  lowStockCount: number;
  /** totalQty / capacity, 0–100+. */
  usagePct: number;
}

export type WarehousePayload = Pick<
  Warehouse,
  'name' | 'type' | 'city' | 'address' | 'manager' | 'phone' | 'capacity' | 'allowNegative' | 'isDefault' | 'isActive' | 'notes'
>;

/** Business-rule codes the warehouses API answers with (409). */
export const WAREHOUSE_ERROR_CODES = {
  /** Warehouse still holds stock — can't be deleted; empty it or deactivate it. */
  hasStock: 'WAREHOUSE_HAS_STOCK',
} as const;

/** Full update payload from a loaded warehouse (e.g. to toggle a flag). */
export function toWarehousePayload(w: Warehouse, patch: Partial<WarehousePayload> = {}): WarehousePayload {
  const { name, type, city, address, manager, phone, capacity, allowNegative, isDefault, isActive, notes } = w;
  return { name, type, city, address, manager, phone, capacity, allowNegative, isDefault, isActive, notes, ...patch };
}

/** Minimal shape for selects and filters. */
export interface WarehouseOption {
  id: string;
  code: string;
  name: string;
  isDefault: boolean;
}

export type WarehouseType = 'main' | 'branch' | 'showroom' | 'transit';

export const WAREHOUSE_TYPES: readonly WarehouseType[] = ['main', 'branch', 'showroom', 'transit'];

export const WAREHOUSE_TYPE_VIEW: Record<WarehouseType, StatusView & { hint: string }> = {
  main: { label: 'مخزن رئيسي', tone: 'info', color: 'var(--bl)', hint: 'يستقبل المشتريات ويغذي الفروع' },
  branch: { label: 'مخزن فرع', tone: 'good', color: 'var(--gr)', hint: 'يخدم مبيعات فرع محدد' },
  showroom: { label: 'صالة عرض', tone: 'warning', color: 'var(--am)', hint: 'بضاعة معروضة للبيع المباشر' },
  transit: { label: 'مخزن عبور', tone: 'neutral', color: 'var(--txt3)', hint: 'بضاعة في الطريق بين المخازن' },
};

/** Usage band for the capacity meter. */
export function usageTone(pct: number): 'good' | 'warning' | 'danger' {
  return pct >= 90 ? 'danger' : pct >= 75 ? 'warning' : 'good';
}
